// Deploy entry: one repository, one Vercel project per origin. MOSAIC_ROLE picks what this origin
// serves (src/roles.ts; every variable per role: docs/deploy.md). In production it runs the bundle
// `bun run build:deploy` made (Vercel's buildCommand), which carries every asset inside it, so
// nothing is read from disk or built on a request. Elsewhere it runs from source.
if (process.env.VERCEL || process.env.NODE_ENV === "production") {
  // @ts-ignore: generated by scripts/build-deploy.ts
  await import("./dist-server/server.js");
} else {
  // A computed path, so Vercel's function bundler does not follow it into the HTML imports.
  const source = "./src/roles";
  await import(source);
}

export {};
